CustomField.formula:
IF(
    Gross_Total__c <= 10000, 0,
    IF(
        Gross_Total__c <= 20000, 0.2,
        IF(
            Gross_Total__c <= 30000, 0.4,
            IF(
                Gross_Total__c <= 40000, 0.6,
                IF(
                    Gross_Total__c <= 50000, 0.8,
                    IF(
                        Gross_Total__c <= 60000, 1,
                        IF(
                            Gross_Total__c <= 75000, 1.2,
                            IF(
                                Gross_Total__c <= 100000, 1.5,
                                IF(
                                    Gross_Total__c <= 150000, 2,
                                    3
                                )
                            )
                        )
                    )
                )
            )
        )
    )
)
